document.querySelectorAll('[data-lab="L03-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const s=root.querySelector('[data-step]'),o=root.querySelector('[data-readout]'),msg=root.querySelector('[data-message]'),en=root.dataset.lang==='en';function update(){const dt=Number(s.value);let x=1,v=0,t=0,points=[[0,1]],max=1;for(let n=0;n<Math.floor(20/dt);n++){v-=.5*dt*x;x+=dt*v;v-=.5*dt*x;t+=dt;max=Math.max(max,Math.abs(x));points.push([t,x]);}const scale=Math.max(1,max),map=(a,b)=>[65+785*a/20,165-120*b/scale];root.querySelector('[data-numeric]').setAttribute('points',points.map(q=>map(...q).join(',')).join(' '));root.querySelector('[data-exact]').setAttribute('points',Array.from({length:401},(_,n)=>map(n*.05,Math.cos(n*.05)).join(',')).join(' '));o.textContent=' Δt = '+dt.toFixed(2)+'; ωΔt = '+dt.toFixed(2)+'; max |x| = '+max.toFixed(3);msg.textContent=(en?'Grey: analytic cos(t); teal: velocity Verlet. ':'灰色：解析解 cos(t)；青色：速度 Verlet。')+(dt<2?(en?'The motion is linearly stable; inspect the phase difference.':'处在线性稳定区间内，仍可观察相位偏差。'):(Math.abs(dt-2)<1e-10?(en?'At the stability boundary, this special initial state alternates between +1 and −1; the sampled oscillation has a large phase error and general perturbations need not remain bounded.':'恰在稳定边界，这个特定初态在+1与−1间交替；采样振动有很大相位误差，一般扰动不保证有界。'):(en?'Beyond the stability boundary, the numerical amplitude grows rapidly.':'超出稳定边界后，数值振幅迅速增长。')))+(en?' The vertical scale expands to include the numerical amplitude.':'纵轴随数值振幅调整，以显示振幅变化。');}s.addEventListener('input',update);root.querySelector('[data-reset]').addEventListener('click',()=>{s.value='0.2';update();});update();});